UPDATE MEMBER_INFO /* AdminMapper.writeNotUser */
   SET USER_STATUS = 'N'
 WHERE MEMBER_ID = #{memberId}

UPDATE MEMBER_INFO /* AdminMapper.writeUser */
   SET USER_STATUS = 'Y'
 WHERE MEMBER_ID = #{memberId}

UPDATE MEMBER_INFO /* AdminMapper.changeRoleAdmin */
   SET USER_ROLE = 'ADMIN'
 WHERE MEMBER_ID = #{memberId}

UPDATE MEMBER_INFO /* AdminMapper.changeRoleUser */
   SET USER_ROLE = 'USER'
 WHERE MEMBER_ID = #{memberId}

UPDATE BOARD /* AdminMapper.restoreBoardContent (삭제된 게시글 복구) */
   SET DELETE_YN = 'N'
 WHERE BOARD_ID = #{boardId}
